<?php
declare(strict_types=1);
define('DESKBOX_API_ENTRY', true);
require dirname(__DIR__) . '/api/_app/town_world_replay.php';

$pdo = new PDO('sqlite::memory:', null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
$pdo->exec('CREATE TABLE town_world_events (event_id INTEGER PRIMARY KEY,world_id TEXT,event_type TEXT,source_key TEXT,public_payload_json TEXT,actor_npc_id TEXT)');
$pdo->exec('ALTER TABLE town_world_events ADD COLUMN target_npc_id TEXT');
$pdo->exec("ALTER TABLE town_world_events ADD COLUMN visibility TEXT NOT NULL DEFAULT 'public'");
$pdo->exec('ALTER TABLE town_world_events ADD COLUMN occurred_at TEXT');
$pdo->exec('ALTER TABLE town_world_events ADD COLUMN expires_at TEXT');
$pdo->exec('ALTER TABLE town_world_events ADD COLUMN created_at TEXT');
$pdo->exec('CREATE TABLE town_world_snapshots (snapshot_id TEXT PRIMARY KEY,world_id TEXT,world_version INTEGER,change_cursor INTEGER,npc_cursor INTEGER,event_cursor INTEGER,navigation_version INTEGER,state_json TEXT,state_sha256 TEXT,created_by TEXT,created_at TEXT)');
$pdo->exec('CREATE TABLE town_world_event_journal (sequence INTEGER PRIMARY KEY AUTOINCREMENT,world_id TEXT,event_type TEXT,payload_json TEXT,schema_version INTEGER,idempotency_key TEXT,created_at TEXT,UNIQUE(world_id,idempotency_key))');
$pdo->exec("CREATE TABLE town_social_matters (matter_id TEXT PRIMARY KEY,kind TEXT NOT NULL DEFAULT '',public_summary TEXT NOT NULL DEFAULT '',state TEXT,failure_reason TEXT,revision INTEGER,updated_at TEXT,closed_at TEXT)");
$pdo->exec('CREATE TABLE town_social_responses (response_id TEXT PRIMARY KEY,matter_id TEXT,resident_id TEXT,option_id TEXT,response_kind TEXT,public_text TEXT,idempotency_key TEXT,created_at TEXT,UNIQUE(matter_id,resident_id))');
$pdo->exec('CREATE TABLE town_social_commitments (commitment_id TEXT PRIMARY KEY,matter_id TEXT,state TEXT,failure_reason TEXT,updated_at TEXT,completed_at TEXT)');
$matter = str_repeat('a', 32); $commitment = str_repeat('b', 32);
$pdo->prepare('INSERT INTO town_social_matters (matter_id,state,failure_reason,revision,updated_at,closed_at) VALUES (?,?,?,?,?,?)')->execute([$matter, 'executing', '', 3, '2026-11-19 12:00:00', null]);
$pdo->prepare('INSERT INTO town_social_commitments VALUES (?,?,?,?,?,?)')->execute([$commitment, $matter, 'executing', '', '2026-11-19 12:00:00', null]);
$now = new DateTimeImmutable('2026-11-19 12:05:00', new DateTimeZone('UTC'));
$event = ['event_type' => 'public_event', 'event_id' => 1, 'source_key' => 'social:1', 'created_at' => '2026-11-19 12:05:00', 'payload' => ['event_id' => 1, 'event_type' => 'social_matter_commitment_completed', 'source_key' => 'social:1', 'payload' => ['matter_id' => $matter, 'commitment_id' => $commitment, 'revision' => 4, 'failure_reason' => '']]];
$pdo->exec("INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json,actor_npc_id) VALUES (1,'main','social_matter_commitment_completed','social:1','{" . '"matter_id":"' . $matter . '","commitment_id":"' . $commitment . '","revision":4,"failure_reason":""' . "}',NULL)");
$snapshotState = ['schema_version' => 1, 'world' => ['world_id' => 'main']]; [$snapshotJson, $snapshotSha] = town_world_snapshot_encode($snapshotState);
$pdo->prepare('INSERT INTO town_world_snapshots VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute(['snap-social-000000000000000000000000001', 'main', 1, 1, 1, 0, 1, $snapshotJson, $snapshotSha, 'worker', '2026-11-19 12:00:00']);
$journalPayload = ['event_id' => 1, 'event_type' => 'social_matter_commitment_completed', 'source_key' => 'social:1', 'payload' => ['matter_id' => $matter, 'commitment_id' => $commitment, 'revision' => 4, 'failure_reason' => '']];
$pdo->prepare('INSERT INTO town_world_event_journal VALUES (?,?,?,?,?,?,?)')->execute([1, 'main', 'public_event', json_encode($journalPayload, JSON_UNESCAPED_UNICODE), 1, 'public_event:1', '2026-11-19 12:05:00']);
$report = town_world_replay_dry_run($pdo, null, 50);
if (!$report['ok'] || !$report['replayable'] || $report['replay_blockers'] !== []) throw new RuntimeException('Social commitment events must be accepted by replay dry-run.');
town_world_replay_apply_event($pdo, $event, $now);
$row = $pdo->query('SELECT state,completed_at FROM town_social_commitments')->fetch();
if ($row['state'] !== 'completed' || $row['completed_at'] !== '2026-11-19 12:05:00') throw new RuntimeException('Social commitment replay must restore its terminal state.');
town_world_replay_apply_event($pdo, $event, $now);
if ((int)$pdo->query('SELECT COUNT(*) FROM town_social_commitments WHERE state=\'completed\'')->fetchColumn() !== 1) throw new RuntimeException('Social commitment replay must be idempotent.');
$open = ['event_type' => 'public_event', 'event_id' => 3, 'source_key' => 'social:3', 'created_at' => '2026-11-19 12:06:30', 'payload' => ['event_id' => 3, 'event_type' => 'social_matter_opened', 'source_key' => 'social:3', 'payload' => ['matter_id' => $matter, 'kind' => 'repair', 'summary' => '修复桥梁', 'revision' => 6]]];
town_world_replay_apply_event($pdo, $open, $now);
$opened = $pdo->query('SELECT kind,public_summary,revision FROM town_social_matters')->fetch();
if ($opened['kind'] !== 'repair' || $opened['public_summary'] !== '修复桥梁' || (int)$opened['revision'] !== 6) throw new RuntimeException('Social matter opened replay must restore bounded public fields.');
$resident = str_repeat('c', 32);
$response = ['event_type' => 'public_event', 'event_id' => 4, 'source_key' => 'social:4', 'created_at' => '2026-11-19 12:06:45', 'payload' => ['event_id' => 4, 'event_type' => 'social_matter_response', 'source_key' => 'social:4', 'payload' => ['matter_id' => $matter, 'resident_id' => $resident, 'option_id' => 'join', 'response_kind' => 'support', 'revision' => 7]]];
town_world_replay_apply_event($pdo, $response, $now);
town_world_replay_apply_event($pdo, $response, $now);
$responseRow = $pdo->query('SELECT option_id FROM town_social_responses')->fetch();
if ($responseRow['option_id'] !== 'join' || (int)$pdo->query('SELECT COUNT(*) FROM town_social_responses')->fetchColumn() !== 1) throw new RuntimeException('Social response replay must be idempotent.');
$close = ['event_type' => 'public_event', 'event_id' => 2, 'source_key' => 'social:2', 'created_at' => '2026-11-19 12:06:00', 'payload' => ['event_id' => 2, 'event_type' => 'social_matter_closed', 'source_key' => 'social:2', 'payload' => ['matter_id' => $matter, 'revision' => 5, 'reason' => '已完成']]];
$pdo->exec("INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json,actor_npc_id) VALUES (2,'main','social_matter_closed','social:2','{" . '"matter_id":"' . $matter . '","revision":5,"reason":"已完成"' . "}',NULL)");
town_world_replay_apply_event($pdo, $close, $now);
$state = $pdo->query('SELECT state,revision FROM town_social_matters')->fetch();
if ($state['state'] !== 'closed' || (int)$state['revision'] !== 7) throw new RuntimeException('Social matter replay must preserve terminal state and monotonic revision: ' . json_encode($state));
echo "town_world_social_replay_test: checks ok\n";
